async function changeWeek(){openModal("Chọn tuần",`<label class="field"><span class="label">Tuần bắt đầu</span><input id="week-pick" class="input" type="date" value="${esc(state.week)}"></label><div class="actions" style="justify-content:flex-end"><button class="btn light" data-action="close">Hủy</button><button class="btn dark" data-action="save-week">Xem tuần</button></div>`);$('#modal [data-action="save-week"]').onclick=()=>{state.week=$('#week-pick').value||state.week;closeModal();renderApp()}}
async function anonymousReport(){openModal("Phản ánh ẩn danh",`<form id="report-form"><div class="notice">Không cần đăng nhập. Không nhập tên hoặc thông tin nhận diện vào nội dung nếu muốn giữ ẩn danh.</div><div class="formgrid" style="margin-top:10px"><label class="field"><span class="label">Nhóm nội dung</span><select id="rp-cat" class="select"><option>Vi phạm nội quy</option><option>Thi đua / điểm số</option><option>Vệ sinh / tài sản</option><option>Ứng xử / mâu thuẫn</option><option>Khác</option></select></label><label class="field"><span class="label">Đối tượng (tuỳ chọn)</span><input id="rp-target" class="input" maxlength="80" placeholder="Tên hoặc mã học sinh"></label><label class="field fullcol"><span class="label">Nội dung</span><textarea id="rp-content" class="textarea" rows="8" maxlength="1000" placeholder="Mô tả sự việc cụ thể, thời điểm nếu biết..." required></textarea></label></div><div class="warning" style="margin-top:10px">Phản ánh cần cụ thể và tôn trọng; đây là kênh để GVCN kiểm tra sự việc, không phải nơi kết luận vi phạm.</div><div class="actions" style="justify-content:flex-end"><button class="btn light" type="button" data-action="close">Hủy</button><button class="btn violet" type="submit">Gửi</button></div></form>`);$('#report-form').onsubmit=async e=>{e.preventDefault();const content=$('#rp-content').value.trim();if(content.length<8)return toast("Nội dung cần rõ hơn.","err");const r={id:id(),category:$('#rp-cat').value,target:$('#rp-target').value.trim(),content,createdAt:Date.now(),status:"new"};let app2=null;try{app2=fb.appApi.initializeApp(FIREBASE_CONFIG,"report_"+Date.now());const auth2=fb.authApi.getAuth(app2),db2=fb.dbApi.getDatabase(app2);await fb.authApi.signInAnonymously(auth2);await fb.dbApi.set(fb.dbApi.ref(db2,`reports/${r.id}`),r);await fb.authApi.signOut(auth2);await fb.appApi.deleteApp(app2);state.reports[r.id]=r;closeModal();toast("Đã gửi phản ánh ẩn danh.","ok");if(!state.user)loginView()}catch(e){console.warn(e);try{if(app2)await fb.appApi.deleteApp(app2)}catch{}await guestReportAuthlessSave(r);closeModal();toast("Đã lưu tạm trên máy; chưa đồng bộ Firebase.","err")}}}
async function toggleUser(uid){if(!isGvcn()||uid===state.user.uid)return;const u=state.users[uid];if(!u)return;const before={...u},next={...u,active:u.active===false};if(!(await dbSet(`users/${uid}`,next)))return toast(firebaseErrMsg("Không cập nhật được tài khoản trên Firebase."),"err");state.users[uid]=next;await writeSystemAudit(next.active?"UNLOCK":"LOCK","user",uid,before,next);renderApp();toast(next.active?"Đã mở tài khoản.":"Đã khóa tài khoản.","ok")}
